#include <omp.h>
#include <vector>
#include <array>

/* Vector x contains values between 0 and 100, inclusive. Count the number of
   values in [0,10), [10, 20), [20, 30), ... and store the counts in `bins`.
   Use OpenMP to compute in parallel.
   Example:

   input: [7, 32, 95, 12, 39, 32, 11, 71, 70, 66]
   output: [1, 2, 0, 3, 0, 0, 1, 2, 0, 1]
*/
void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize bins to zero
    bins.fill(0);

    // Use private per-thread bin arrays to avoid race conditions
    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins;
        local_bins.fill(0);

        #pragma omp for nowait
        for (size_t i = 0; i < x.size(); ++i) {
            double val = x[i];
            // Determine bin index: [0,10) -> 0, [10,20) -> 1, ..., [90,100) -> 9
            // For value 100, it would be bin 10, but we only have 10 bins (0-9)
            // The problem states values are between 0 and 100 inclusive.
            // Bin 9 is [90, 100). What about 100?
            // Looking at the example: 95 goes to bin 9 (index 9). 
            // 100 would be index 10 which is out of bounds.
            // The problem says bins are [0,10), [10,20), ..., [90,100). 
            // So 100 is not in any bin? Or perhaps the last bin is [90,100]?
            // Let's check: the example has 95 in bin 9. If 100 were included, it might go to bin 9 as well.
            // Given the bin definition [90,100), 100 is excluded. But the problem says values are up to 100 inclusive.
            // I'll assume values of exactly 100 should go to bin 9 (the last bin), treating the last bin as [90,100].
            // Actually, let's use integer division: bin = val / 10, clamped to 9.
            int bin_idx = static_cast<int>(val / 10.0);
            if (bin_idx >= 10) bin_idx = 9;
            if (bin_idx < 0) bin_idx = 0;
            local_bins[bin_idx]++;
        }

        // Reduce local_bins into global bins
        #pragma omp critical
        {
            for (int i = 0; i < 10; ++i) {
                bins[i] += local_bins[i];
            }
        }
    }
}
